    wb = load_workbook('/work/output/Greenfield_CostBenefit_Analysis.xlsx')
    out = []
    for ws in wb.worksheets:
        for row in ws.iter_rows():
            for c in row:
                if c.value is not None:
                    out.append(str(c.value))
    return wb.sheetnames, ' '.join(out)

def text_docx():
    d = Document('/work/output/Greenfield_Decision_Briefing_Memo.docx')
    parts = [p.text for p in d.paragraphs]
    for t in d.tables:
        for r in t.rows:
            for c in r.cells:
                parts.append(c.text)
    return len(d.paragraphs), len(d.tables), ' '.join(parts)

def text_pptx():
    pr = Presentation('/work/output/Greenfield_Council_Presentation.pptx')
    parts = []
    charts = 0
    tables = 0
    for i, s in enumerate(pr.slides, 1):
        for sh in s.shapes:
            if sh.has_text_frame:
                parts.append(sh.text_frame.text)
            if sh.has_chart:
                charts += 1
            if sh.has_table:
                tables += 1
                for r in sh.table.rows:
                    for c in r.cells:
                        parts.append(c.text)
    return len(pr.slides._sldIdLst), charts, tables, ' '.join(parts)

