    rd = k in dx
    rp = k in px
    status = 'OK ' if (rx and rd and rp) else ('-- ' if (rx or rd or rp) else 'MISSING')
    print(f"{status} {label:34s} xlsx={rx} docx={rd} pptx={rp}")

bad = re.findall(r'theFire| teh |  ,|,,|\$\$|\bteh\b', dx + ' ' + px)
